initial_condition:
with {
    the SUT containing a Hosted @context and the default Cached Core Context.
        }

test_cases.when:
when {
    the SUT receives a Request from the client containing:
        URL set to '/ngsi-ld/v1/jsonldContexts/{contextId}'
        method set to 'GET'
        Serve a @context with contextID '${uri}' and details '${EMPTY}'
}

when {
    the SUT receives a Request from the client containing:
        URL set to '/ngsi-ld/v1/jsonldContexts/{contextId}'
        method set to 'GET'
        Serve a @context with contextID '${uri}' and details 'false'
}
